import {actions} from './actions.js';
import {uid,dayKey} from './store.js';
import {muscleGroups,personalPresets} from './training-data.js';
import {readiness,recommendations,currentLevel,evaluateLevel,goalStatuses,substitutions,adaptiveDifficulty,filterHistory,equipmentAllows} from './training.js';
import {personalStatuses,weeklyPersonalSummary,availableWindow} from './schedule.js';
export function createTrainingUI(ctx){const data=()=>ctx.data(),e=ctx.esc,field=ctx.field;let builder=null,historyFilters={};
 const profile=()=>data().equipmentProfiles.find(p=>p.id===ctx.pref().equipmentContext)||data().equipmentProfiles[0];
 const modeOptions=selected=>['Normal','Light / Rebuild','Skill','Dominance','Recovery'].map(m=>`<option ${m===selected?'selected':''}>${m}</option>`).join('');
 const exercise=(id)=>data().exercises.find(x=>x.id===id);
 const plan=(ex,level=null,trial=null)=>({exerciseId:ex.id,name:ex.name,sets:trial?.sets||2,reps:trial?.reps||(ex.measurement==='reps'?8:1),weight:trial?.load||0,durationSeconds:trial?.seconds||(ex.measurement==='duration'?15:0),distanceMeters:trial?.distance||(ex.measurement==='distance'?ex.category==='Running'?1000:20:0),tempo:trial?.tempo?'Slow eccentric':'Controlled',restSeconds:60,difficultyTarget:7,notes:''});
 const runSession=async(kind,exercises,name,mode='Normal',proof=null,sport=null,templateId=null,recommendation=null)=>{const s=await actions.dispatch('startSession',{kind,exercises,name,mode,proof,sport,templateId,recommendation});await ctx.refresh();ctx.showSession(s.id)};
 function trainPage(){const templates=data().templates.filter(t=>t.type==='workout'&&!t.archived),p=profile();return ctx.heading('Train with intent.','Your goals. Your equipment. Your next useful session.',`<button class="white" data-action="custom">+ Create workout</button>`)+`<div class="grid"><article class="card training-card"><div class="card-head"><span class="eyebrow">MAIN WORKOUT</span><span class="pill">${e(p?.name||'Home')}</span></div><h2>Pull / foundation</h2><p class="muted">Your main session stays independent of every extra.</p><div class="actions"><button class="white" data-action="start" data-kind="Main">Open main workout ↗</button><button data-action="lightSecond">Second / Light-Rebuild</button></div></article><article class="card"><h2>Still hungry?</h2><p class="muted">Useful options from your history, mastery path, recovery, and available time.</p><div class="actions"><button data-action="hungry">Recommendations ↗</button><button data-action="extraArea">Choose a muscle</button></div></article><article class="card wide"><div class="card-head"><h2>Today's sessions</h2><button data-action="equipment">My equipment · ${e(p?.name)}</button></div>${data().sessions.filter(s=>s.date===dayKey()).map(s=>`<div class="row"><div class="row-main"><h3>${e(s.name)}</h3><p>${s.kind} · ${s.mode||'Normal'} · ${s.status==='partial'?'Ended — partial':s.status} · ${s.logs.length} saved sets${s.supersededBy?' · preserved duplicate':''}</p></div><button data-action="session" data-id="${s.id}">Open</button></div>`).join('')||'<p class="empty">Start deliberately. Your logs save as you go.</p>'}</article><article class="card"><div class="card-head"><h2>Your workout templates</h2><button data-action="custom">+</button></div>${templates.map(t=>`<div class="row"><div class="row-main"><h3>${e(t.name)}</h3><p>${t.exercises.length} movements · revision ${t.revision||1}</p><div class="actions"><button data-action="editTemplate" data-id="${t.id}">Edit</button><button data-action="duplicateTemplate" data-id="${t.id}">Duplicate</button><button data-action="archiveTemplate" data-id="${t.id}">Archive</button></div></div><button class="white" data-action="usetemplate" data-id="${t.id}">Start</button></div>`).join('')||'<p class="empty">Save a session you want to repeat.</p>'}</article><article class="card"><h2>Movement & capacity</h2><p class="muted">Carry load, distance, duration, grip, and posture. Run/walk with pace and intervals.</p><div class="actions"><button data-action="carrySession">Carry training</button>${ctx.pref().sports&&ctx.pref().sportToggles?.Running!==false?'<button data-action="runSession">Run / walk</button>':''}<button data-action="sportsSettings">Sports modules</button></div><p class="legend">Turning sports off hides its recommendations and keeps all progress.</p></article><article class="card wide"><h2>Exercise library</h2><p class="muted">${data().exercises.length} structured movements · alternatives that fit your context</p><div class="actions"><button data-action="exerciseLibrary">Explore movements</button><button data-action="soreness">Soreness check-in</button><button data-action="readiness">Readiness / why?</button></div></article></div>`}
 function dominancePage(){return ctx.heading('Command your level.','Repeatable proof unlocks the path. XP never bypasses it.')+`<div class="skill-grid">${data().skillDefinitions.map(skill=>{const level=currentLevel(skill,data()),state=evaluateLevel(skill,level,data());return `<article class="card"><div class="card-head"><span class="eyebrow">${e(skill.category.toUpperCase())}</span><span class="skill-icon">${skill.icon||'◇'}</span></div><h2>${e(skill.name)}</h2><div class="tree">${skill.levelDefinitions.map(l=>{const earned=data().masteryAwards.some(a=>a.skill===skill.id&&a.levelId===l.id);return `<button class="node ${earned?'earned':l.id===level.id?'current':'locked'}" data-action="skillLevel" data-skill="${skill.id}" data-level="${l.id}">${e(l.name)} ${earned?'★':l.id===level.id?'':'· locked'}</button>`}).join('')}</div><div class="stages"><b>${state.stage}</b> · ${e(level.name)}</div>${ctx.progress(state.percent,skill.name)}${state.trials.map(t=>`<div class="trial"><div><strong>${e(t.pillar)}</strong><small>${e(t.label)}</small></div><span>${t.complete?'✓':'○'}</span></div>`).join('')}<div class="trial"><div><strong>Consistency</strong><small>Qualifying practice on different days</small></div><span>${Math.min(state.days,level.sessions)} / ${level.sessions}</span></div><div class="actions"><button data-action="skillLevel" data-skill="${skill.id}" data-level="${level.id}">Learn / history / why?</button><button class="white" data-action="proofStart" data-skill="${skill.id}" data-level="${level.id}">Train this level</button><button data-action="trial" data-skill="${skill.id}" data-level="${level.id}">Log evidence</button></div></article>`}).join('')}</div>`}
 function focusSection(){return `<article class="card"><div class="card-head"><h2>Dominance in focus</h2><button data-route="Dominance">↗</button></div>${data().skillDefinitions.filter(s=>['pull','curl','carry'].includes(s.id)).map(s=>{const l=currentLevel(s,data()),v=evaluateLevel(s,l,data());return `<div class="row"><div class="symbol">${s.icon}</div><div class="row-main"><h3>${e(s.name)}</h3><p>${e(l.name)} · ${v.stage}</p>${ctx.progress(v.percent,s.name)}</div><span>${v.percent}%</span></div>`}).join('')}</article>`}
 function todayExtras(){const blocks=data().events.filter(x=>x.date===dayKey()&&x.category==='Personal Time'),window=availableWindow(data().events);return `<article class="card"><div class="card-head"><h2>Personal Time</h2><span>🤍</span></div>${blocks.map(b=>`<div class="row"><div class="row-main"><h3>${e(b.name)}</h3><p>${e(b.time)} · ${b.durationMinutes} min · ${e(b.status)}</p></div><button data-action="personalEdit" data-id="${b.id}">Open</button></div>`).join('')||'<p class="empty">Make room for your people and your life.</p>'}<div class="actions"><button data-action="personalCreate">+ Protect time</button><button data-action="planner">Schedule / Planner</button></div><p class="legend">${window.event?.category==='Personal Time'?e(window.reason):'A real commitment. No productivity requirement or relationship streak.'}</p></article><article class="card"><div class="card-head"><h2>Body readiness</h2><button data-action="soreness">Check in</button></div>${['Biceps','Grip','Quads'].map(m=>{const r=readiness(m,data(),dayKey());return `<div class="row"><div class="row-main"><strong>${m}</strong><p>${e(r.confidence)}</p></div><button data-action="readiness" data-muscle="${m}">${r.score===null?'Not logged':r.score+'% · Why?'}</button></div>`}).join('')}<p class="legend">Advisory estimates. You stay in control.</p></article>`}
 function personalBanner(){const w=availableWindow(data().events);return w.event?.category==='Personal Time'&&w.minutes<=60?`<aside class="notice wide"><strong>${e(w.event.name)} ${w.minutes===0?'is active':'in '+w.minutes+' min'}</strong><p>Save a longer optional session for later. Protected time matters on its own.</p><button data-action="personalEdit" data-id="${w.event.id}">View commitment</button></aside>`:''}
 function profileExtras(){const week=weeklyPersonalSummary(data().events);return `<article class="card wide"><div class="card-head"><h2>Weekly review</h2><button data-action="planner">Open Planner</button></div><div class="metrics"><div class="metric"><strong>${week.completed}</strong><small>Protected personal-time blocks completed</small></div><div class="metric"><strong>${data().masteryAwards.length}</strong><small>Permanent mastery awards</small></div><div class="metric"><strong>${data().records.length}</strong><small>Current performance records</small></div></div><p class="legend">${week.text}</p></article><article class="card wide"><h2>Personal records</h2>${data().records.map(r=>`<div class="row"><div class="row-main"><h3>${e(exercise(r.exerciseId)?.name||r.exerciseId)}</h3><p>${e(r.type)} · ${e(r.date)}</p></div><strong>${r.value.toFixed(r.unit==='s/km'?1:0)} ${e(r.unit)}</strong></div>`).join('')||'<p class="empty">Your recorded performance will surface here. Pain earns no bonus.</p>'}</article>`}
 function historySection(){const sessions=filterHistory(data().sessions,historyFilters,data().exercises,data().records).sort((a,b)=>b.date.localeCompare(a.date));return `<article class="card wide"><div class="card-head"><h2>Training history</h2><button data-action="historyFilters">Filter · ${Object.values(historyFilters).filter(Boolean).length}</button></div>${sessions.map(s=>`<div class="row"><div class="row-main"><h3>${e(s.name)}</h3><p>${s.date} · ${s.kind} · ${s.mode||'Normal'} · ${s.status==='partial'?'Ended — partial':s.status} · ${s.logs.length} sets</p></div><button data-action="session" data-id="${s.id}">View</button></div>`).join('')||'<p class="empty">No matching sessions.</p>'}</article>`}
 function hungry(source=data()){const result=recommendations(source,dayKey());ctx.modal('Still hungry?',`<p class="muted">${e(result.message)}</p>${result.options.map(o=>`<div class="row"><div class="row-main"><h3>${e(o.name)}</h3><p>About ${o.duration} min · ${o.readiness===null?'readiness unknown':o.readiness+'% estimated readiness'}</p><details><summary>Why?</summary>${o.reasons.map(r=>`<p class="legend">${e(r)}</p>`).join('')}</details></div>${o.mode==='Light / Rebuild'?`<button data-action="freeExtra" data-exercise="${o.exerciseId}" data-mode="Light / Rebuild" data-low-readiness="true">Light / Rebuild ↗</button>`:`<button data-action="proofStart" data-skill="${o.skill}" data-level="${o.levelId}" data-trial="${o.trialId}">Train ↗</button>`}</div>`).join('')||'<div class="notice">No optional session fits the logged window. Protect your commitment; training can wait.</div>'}${result.deferred.length?`<details style="margin:18px 0"><summary>Save longer options for later (${result.deferred.length})</summary>${result.deferred.map(o=>`<p>${e(o.name)} · about ${o.duration} min</p>`).join('')}</details>`:''}<div class="actions"><button data-action="extraArea">Choose a muscle / Train anyway</button><button data-action="personalCreate">Protect personal time</button></div>`)}
 function extraArea(selected=''){ctx.modal('Extra Training',`<p class="muted">Free targeted practice or a specific mastery trial. Your Main workout stays saved.</p>${Object.entries(muscleGroups).map(([group,items])=>`<details ${group==='Upper'?'open':''} style="margin:20px 0"><summary>${group==='Upper'?'Upper body / Arms':group==='Lower'?'Lower body':group}</summary><div class="actions" style="margin-top:12px">${items.map(m=>`<button data-action="extraMuscle" data-muscle="${m}">${m}</button>`).join('')}</div></details>`).join('')}`);if(selected)extraMuscle(selected)}
 function extraMuscle(muscle,source=data()){const r=readiness(muscle,source,dayKey()),p=profile();const group=muscle.toLowerCase();let choices=data().exercises.filter(x=>equipmentAllows(x,p)&&(x.targetMuscles.some(m=>m.toLowerCase()===group)||x.category.toLowerCase()===group));if(['Full Upper','Full Lower','Full Body','Calisthenics','Mobility','Cardio','Recovery'].includes(muscle)){choices=data().exercises.filter(x=>equipmentAllows(x,p)&&(muscle==='Full Body'||(muscle==='Full Upper'&&['Chest','Back','Shoulders','Biceps'].includes(x.category))||(muscle==='Full Lower'&&['Quads','Hamstrings','Glutes','Calves'].includes(x.category))||(['Mobility','Recovery'].includes(muscle)&&x.category==='Mobility')||(muscle==='Calisthenics'&&x.resistance==='bodyweight')||(muscle==='Cardio'&&x.category==='Running'&&ctx.pref().sports)))}ctx.modal(muscle+' / Extra Training',`<p>${r.score===null?'Readiness not yet logged.':r.score+'% readiness estimate · '+e(r.confidence)}</p><details><summary>Why?</summary>${r.reasons.map(x=>`<p class="legend">${e(x)}</p>`).join('')}</details><div class="notice">${e(availableWindow(source.events).reason)} Training remains your choice; this does not reserve schedule time.</div>${choices.slice(0,8).map(x=>`<div class="row"><div class="row-main"><h3>${e(x.name)}</h3><p>${e(x.movementType)}</p></div><button data-action="freeExtra" data-exercise="${x.id}">Free training</button><button data-action="freeExtra" data-exercise="${x.id}" data-mode="Light / Rebuild">Light / Rebuild</button>${x.relatedDominancePath?`<button data-action="proofStart" data-skill="${x.relatedDominancePath}">Dominance path</button>`:''}</div>`).join('')||'<p class="empty">No matching movement fits your equipment. Choose another context or movement.</p>'}`)}
 function soreness(){ctx.modal('Soreness check-in',`<form class="fields"><label class="field">Muscle<select name="muscle">${[...new Set(Object.values(muscleGroups).flat().filter(m=>!muscleGroups.General.includes(m)))].map(m=>`<option>${m}</option>`).join('')}</select></label><label class="field">Soreness<select name="rating">${['None','Mild','Noticeable','High','Severe'].map((s,i)=>`<option value="${i}">${i} — ${s}</option>`).join('')}</select></label><p class="legend">Soreness informs recommendations; it never erases your progress.</p><button class="white">Save check-in</button></form>`,f=>actions.dispatch('logSoreness',{muscle:f.get('muscle'),rating:+f.get('rating')}))}
 function showReadiness(muscle=''){const muscles=muscle?[muscle]:['General','Chest','Back','Biceps','Triceps','Grip','Quads','Hamstrings','Glutes','Abs'];ctx.modal('Readiness / logged inputs',muscles.map(m=>{const r=readiness(m,data(),dayKey());return `<details ${muscle?'open':''} style="margin:18px 0"><summary>${m} — ${r.score===null?'not enough data':r.score+'%'}</summary><p class="legend">${r.confidence} · an advisory estimate, not a medical measurement</p>${r.reasons.map(x=>`<p>${e(x)}</p>`).join('')}<button data-action="extraMuscle" data-muscle="${m}">Train Anyway / Light-Rebuild</button></details>`}).join('')+'<button data-action="soreness">Log soreness</button>')}
 function showLevel(skillId,levelId){const skill=data().skillDefinitions.find(s=>s.id===skillId),level=skill.levelDefinitions.find(l=>l.id===levelId)||currentLevel(skill,data()),state=evaluateLevel(skill,level,data()),index=skill.levelDefinitions.indexOf(level),locked=skill.levelDefinitions.slice(0,index).some(l=>!data().masteryAwards.some(a=>a.skill===skillId&&a.levelId===l.id)),x=exercise(level.exerciseId);ctx.modal(e(skill.name)+' / '+e(level.name),`<span class="eyebrow">${locked?'LOCKED':state.stage} // ${e(x.name)}</span><p>${e(level.cues)}</p>${x.safety.cues.map(c=>`<p class="legend">${e(c)}</p>`).join('')}<h3>Requirements</h3>${state.trials.map(r=>`<p>${r.complete?'✓':'○'} ${e(r.label)}</p>`).join('')}<p>Consistency: ${state.days}/${level.sessions} different qualifying days.</p>${locked?'<div class="notice">Earlier levels need repeatable proof first. XP and coins cannot satisfy them.</div>':''}<h3>History</h3>${state.attempts.map(a=>`<p class="legend">${a.date} · ${e(a.trial)} · ${a.sets} sets · ${a.reps} reps · ${a.seconds} s · ${a.distance} m${a.pain?' · pain / not proof':''}</p>`).join('')||'<p class="empty">No attempts yet.</p>'}<div class="actions"><button data-action="exerciseLibrary" data-exercise="${x.id}">Movement / alternatives</button>${!locked?`<button class="white" data-action="proofStart" data-skill="${skillId}" data-level="${level.id}">Train</button><button data-action="trial" data-skill="${skillId}" data-level="${level.id}">Log evidence</button><button data-action="ruleEditor" data-skill="${skillId}" data-level="${level.id}">Configure future trial</button>`:''}</div>`)}
 function proofStart(skillId,levelId,trialId){const skill=data().skillDefinitions.find(s=>s.id===skillId),level=skill.levelDefinitions.find(l=>l.id===levelId)||currentLevel(skill,data()),x=exercise(level.exerciseId);ctx.modal('Train / '+e(level.name),`<form class="fields"><label class="field">Unfinished / current requirement<select name="trial">${level.requirements.map(r=>`<option value="${r.id}" ${r.id===trialId?'selected':''}>${e(r.label)}</option>`).join('')}</select></label><p class="muted">Your logged sets contribute evidence to this trial. Technique and difficulty feedback are required.</p><div class="notice">${e(availableWindow(data().events).reason)} This creates an independent Extra session; it does not schedule over commitments.</div><button class="white">Begin Dominance Training</button></form>`,async f=>{const trial=level.requirements.find(r=>r.id===f.get('trial'));const s=await actions.dispatch('startSession',{kind:'Extra',name:skill.name+' / '+level.name,exercises:[plan(exercise(trial.exerciseId||x.id),level,trial)],mode:'Dominance',proof:{skill:skill.id,levelId:level.id,trialId:trial.id},sport:skill.sport||null});setTimeout(()=>ctx.showSession(s.id),50)})}
 function logTrial(skillId,levelId){const skill=data().skillDefinitions.find(s=>s.id===skillId),level=skill.levelDefinitions.find(l=>l.id===levelId)||currentLevel(skill,data());const attemptId=uid();ctx.modal('Mastery evidence / '+e(level.name),`<form class="fields"><label class="field">Trial<select name="trial">${level.requirements.map(r=>`<option value="${r.id}">${e(r.label)}</option>`).join('')}</select></label>${field('Sets','sets','number',0,'min="0" max="100" required')}${field('Minimum reps in each set','reps','number',0,'min="0" max="1000" required')}${field('Minimum seconds in each set','seconds','number',0,'min="0" max="3600" required')}${field('Minimum distance per effort · m','distance','number',0,'min="0" max="100000" required')}${field('Minimum resistance · lb','load','number',0,'min="0" max="2000" step="0.5" required')}${field('Difficulty · 1–10','difficulty','number',7,'min="1" max="10" required')}<label><input name="form" type="checkbox" style="width:auto"> Controlled form, range, and pacing</label><label><input name="tempo" type="checkbox" style="width:auto"> Slow eccentric / tempo target met</label><label><input name="pain" type="checkbox" style="width:auto"> Pain occurred</label>${field('Notes','notes','text')}<button class="white">Save evidence</button></form>`,async f=>{await actions.dispatch('recordDominanceAttempt',{attempt:{id:attemptId,skill:skill.id,levelId:level.id,trial:f.get('trial'),sets:+f.get('sets'),reps:+f.get('reps'),seconds:+f.get('seconds'),distance:+f.get('distance'),load:+f.get('load'),difficulty:+f.get('difficulty'),form:f.has('form'),tempo:f.has('tempo'),pain:f.has('pain'),notes:f.get('notes')}});ctx.toast('Evidence saved. Each level can be awarded only once.')})}
 function library(selected=''){const list=selected?data().exercises.filter(x=>x.id===selected):data().exercises;ctx.modal('Exercise library',list.map(x=>`<details ${selected?'open':''} style="margin:20px 0"><summary>${e(x.name)} · ${e(x.category)}</summary><p>${e(x.movementType)} · ${e(x.measurement||'reps')} · ${e(x.laterality||'bilateral')}</p><p>Primary: ${(x.primaryMuscles||x.targetMuscles).map(e).join(', ')}<br>Secondary: ${(x.secondaryMuscles||[]).map(e).join(', ')}</p><p>Equipment: ${x.equipment.length?x.equipment.map(e).join(', '):'No equipment'}</p><p class="legend">${x.safety.cues.map(e).join('. ')}</p><h3>Regressions / alternatives</h3>${substitutions(x,data().exercises,profile()).map(a=>`<p>${e(a.name)} · ${a.relationship}</p>`).join('')||'<p>No matching option in this context.</p>'}<p>Progressions: ${x.progressions.map(id=>e(exercise(id)?.name||id)).join(', ')||'Increase control before difficulty'}</p><p>PRs: ${(x.supportedPRTypes||[]).map(e).join(', ')}</p><p>Dominance: ${e(x.relatedDominancePath||'not linked')}</p></details>`).join(''))}
 function replaceMovement(sessionId,index){const s=data().sessions.find(s=>s.id===sessionId),movement=s.exercises[index],x=exercise(movement.exerciseId)||data().exercises.find(x=>x.name===movement.name);const choices=x?substitutions(x,data().exercises,profile()):data().exercises.filter(x=>equipmentAllows(x,profile()));ctx.modal("Can't do this / alternatives",`<p class="muted">Keep the training intent. Saved sets retain the original movement.</p>${choices.map(x=>`<div class="row"><div class="row-main"><h3>${e(x.name)}</h3><p>${e(x.relationship||x.movementType)} · ${x.equipment.length?x.equipment.map(e).join(', '):'No equipment'}</p></div><button data-action="chooseReplacement" data-id="${sessionId}" data-index="${index}" data-exercise="${x.id}">Use this</button></div>`).join('')||'<p class="empty">No suitable library option for this equipment. Switch context or edit your equipment.</p>'}<button data-action="equipment">Change equipment context</button>`)}
 function adaptive(exerciseId){const x=exercise(exerciseId),result=adaptiveDifficulty(exerciseId,data());ctx.modal(result.ready?'Ready for more?':'Effort / recent history',`<h3>${e(x?.name||'Movement')}</h3><p>${e(result.reason)}</p><div class="actions"><button data-action="exerciseLibrary" data-exercise="${exerciseId}">Harder variation / control options</button>${x?.relatedDominancePath?`<button data-action="proofStart" data-skill="${x.relatedDominancePath}">Start proof trial</button>`:''}<button data-action="keepLevel">Keep current level</button></div><p class="legend">Recommendations never automatically increase your load or add endless reps.</p>`)}
 function personalCreate(){ctx.modal('Protect Personal Time',`<form class="fields"><label class="field">Preset<select name="preset">${personalPresets.map(p=>`<option>${p}</option>`).join('')}<option>Custom label</option></select></label>${field('Custom label · optional','label','text','','maxlength="100"')}${field('Date / recurrence start','date','date',dayKey(),'required')}${field('Start time','time','time','20:00','required')}${field('Flexible duration · minutes','durationMinutes','number',60,'min="1" max="1440" required')}<label><input name="recurring" type="checkbox" style="width:auto"> Repeat on selected weekdays</label><div class="actions">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<label><input name="day:${i}" type="checkbox" style="width:auto" ${i===new Date().getDay()?'checked':''}> ${d}</label>`).join('')}</div>${field('Repeat until · optional','until','date','')}<p class="legend">A real commitment. No productivity requirement, XP by duration, or streak pressure.</p><button class="white">Protect this time</button></form>`,async f=>{const name=f.get('label').trim()||f.get('preset');if(name==='Custom label')throw Error('Enter your custom label.');await actions.dispatch('createPersonalTime',{block:{name,date:f.get('date'),time:f.get('time'),durationMinutes:+f.get('durationMinutes'),status:'PLANNED',weekdays:[0,1,2,3,4,5,6].filter(i=>f.has('day:'+i)),until:f.get('until')||null},recurring:f.has('recurring')});ctx.toast('Personal Time protected. No relationship score attached.')})}
 function personalEdit(id,moveTonight=false){const b=data().events.find(b=>b.id===id);ctx.modal(e(b.name),`<form class="fields">${field('Date','date','date',moveTonight?dayKey():b.date,'required')}${field('Time','time','time',moveTonight?'20:00':b.time,'required')}${field('Flexible duration · minutes','durationMinutes','number',b.durationMinutes,'min="1" max="1440" required')}<label class="field">Status<select name="status">${personalStatuses.map(s=>`<option ${s===(moveTonight?'MOVED':b.status)?'selected':''}>${s}</option>`).join('')}</select></label><p class="legend">${b.recurrenceId?'This changes only this occurrence; the recurring pattern stays intact.':'Move this block without deleting it.'}</p><button class="white">Save commitment</button></form>`,f=>actions.dispatch('updatePersonalTime',{eventId:id,date:f.get('date'),time:f.get('time'),durationMinutes:+f.get('durationMinutes'),status:f.get('status')}))}
 function planner(){const today=dayKey(),events=data().events.filter(x=>x.date>=today).sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time)),week=weeklyPersonalSummary(data().events);ctx.modal('Schedule / Caelum Planner',`<div class="actions"><button data-action="personalCreate">+ Personal Time</button><button data-action="event">+ Other commitment</button></div>${events.map(b=>`<div class="row"><div class="row-main"><h3>${e(b.name)} ${b.protected?'🤍':''}</h3><p>${b.date} · ${b.time} · ${b.durationMinutes||'flexible'} ${b.durationMinutes?'min':''} · ${b.status}</p></div><button data-action="${b.category==='Personal Time'?'personalEdit':'eventstatus'}" data-id="${b.id}">Move / update</button></div>`).join('')||'<p class="empty">No upcoming commitments logged.</p>'}<details style="margin:20px 0"><summary>Recurring Personal Time</summary>${data().personalRecurrences.filter(r=>!r.archived).map(r=>`<div class="row"><div><h3>${e(r.name)}</h3><p>${r.time} · ${r.durationMinutes} min · ${r.weekdays.map(i=>['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][i]).join(', ')}</p></div><button data-action="archiveRecurrence" data-id="${r.id}">Stop future recurrence</button></div>`).join('')}</details><p>Protected personal time: ${week.completed} blocks completed this week.</p><p class="legend">${week.text}</p>`)}
 function equipment(){ctx.modal('My equipment / manual context',`<form class="fields"><label class="field">Context<select name="context">${data().equipmentProfiles.map(p=>`<option value="${p.id}" ${p.id===profile()?.id?'selected':''}>${e(p.name)}</option>`).join('')}</select></label><label class="field">Available equipment in this context · one per line<textarea name="equipment" rows="6">${e(profile()?.equipment.join('\n'))}</textarea></label><p class="legend">Use equipment labels such as dumbbells, machines, pull-up bar, bands, treadmill, cable machine, sandbag, carry object. An empty profile still includes no-equipment movements. No GPS is used.</p><button class="white">Save context</button></form>`,async f=>{const p=data().equipmentProfiles.find(p=>p.id===f.get('context'));await actions.dispatch('saveEquipmentProfile',{profile:{...p,equipment:f.get('equipment').split('\n').map(x=>x.trim()).filter(Boolean)}});await actions.dispatch('setEquipmentContext',{profileId:p.id})});document.querySelector('#modal select[name="context"]').onchange=ev=>{document.querySelector('#modal textarea').value=data().equipmentProfiles.find(p=>p.id===ev.target.value).equipment.join('\n')}}
 function openBuilder(id=''){const t=data().templates.find(t=>t.id===id);builder=t?structuredClone(t):{id:uid(),type:'workout',name:'',description:'',mode:'Normal',exercises:[plan(exercise('curl'))]};renderBuilder()}
 function readBuilder(){const form=document.querySelector('#modal form');if(!form)return;const f=new FormData(form);builder.name=f.get('name');builder.description=f.get('description');builder.mode=f.get('mode');builder.exercises=builder.exercises.map((row,i)=>({...row,exerciseId:f.get('exercise:'+i)||null,name:f.get('movementName:'+i),sets:+f.get('sets:'+i),reps:+f.get('reps:'+i),weight:+f.get('weight:'+i),durationSeconds:+f.get('duration:'+i),distanceMeters:+f.get('distance:'+i),tempo:f.get('tempo:'+i),restSeconds:+f.get('rest:'+i),notes:f.get('notes:'+i),difficultyTarget:+f.get('difficulty:'+i)}))}
 function renderBuilder(){ctx.modal(builder.name?'Edit workout / '+e(builder.name):'Create workout',`<form class="fields">${field('Workout name','name','text',builder.name,'required maxlength="100"')}${field('Description','description','text',builder.description||'')}<label class="field">Workout mode<select name="mode">${modeOptions(builder.mode)}</select></label>${builder.exercises.map((row,i)=>`<details open class="builder-row"><summary>${i+1}. ${e(row.name)}</summary><label class="field">Library movement<select name="exercise:${i}"><option value="">Custom movement</option>${data().exercises.map(x=>`<option value="${x.id}" ${x.id===row.exerciseId?'selected':''}>${e(x.name)}</option>`).join('')}</select></label>${field('Movement name','movementName:'+i,'text',row.name,'required')}<div class="builder-grid">${field('Sets','sets:'+i,'number',row.sets,'min="1" max="100" required')}${field('Reps','reps:'+i,'number',row.reps,'min="1" max="1000" required')}${field('Resistance · lb','weight:'+i,'number',row.weight,'min="0" max="2000" step="0.5" required')}${field('Duration · seconds','duration:'+i,'number',row.durationSeconds||0,'min="0" max="100000" required')}${field('Distance · meters','distance:'+i,'number',row.distanceMeters||0,'min="0" max="100000" required')}${field('Rest · seconds','rest:'+i,'number',row.restSeconds||60,'min="0" max="100000" required')}</div>${field('Tempo','tempo:'+i,'text',row.tempo||'Controlled')}${field('Notes','notes:'+i,'text',row.notes||'')}${field('Difficulty target · 1–10','difficulty:'+i,'number',row.difficultyTarget||7,'min="1" max="10" required')}<div class="actions"><button type="button" data-action="builderUp" data-index="${i}" ${i===0?'disabled':''}>↑ Move up</button><button type="button" data-action="builderDown" data-index="${i}" ${i===builder.exercises.length-1?'disabled':''}>↓ Move down</button><button type="button" data-action="builderRemove" data-index="${i}">Remove</button></div></details>`).join('')}<button type="button" data-action="builderAdd">+ Add movement</button><button class="white">Save reusable template</button></form>`,async()=>{readBuilder();await actions.dispatch('saveWorkoutTemplate',{template:builder});ctx.toast('Template saved. Existing sessions keep their original snapshot.')});document.querySelectorAll('#modal select[name^="exercise:"]').forEach(select=>select.onchange=()=>{readBuilder();const index=+select.name.split(':')[1],x=exercise(select.value);if(x)builder.exercises[index]={...plan(x),sets:builder.exercises[index].sets};renderBuilder()})}
 function movementSession(kind){const carry=kind==='Carry',choices=data().exercises.filter(x=>carry?x.category==='Carry':x.category==='Running');ctx.modal(carry?'Carry training':'Running / walking',`<form class="fields"><label class="field">Movement<select name="exercise">${choices.map(x=>`<option value="${x.id}">${e(x.name)}</option>`).join('')}</select></label><label class="field">Mode<select name="mode">${modeOptions('Normal')}</select></label><p class="legend">${carry?'Log load, meters, seconds, grip status, and posture in each effort.':'Log meters and seconds for pace, interval notes, and perceived effort. Running has its own progression rules.'}</p><button class="white">Start independent session</button></form>`,async f=>{const x=exercise(f.get('exercise')),s=await actions.dispatch('startSession',{kind:carry?'Extra':'Sports',sport:carry?null:'Running',name:x.name,mode:f.get('mode'),exercises:[plan(x)]});setTimeout(()=>ctx.showSession(s.id),50)})}
 function ruleEditor(skillId,levelId){const skill=data().skillDefinitions.find(s=>s.id===skillId),level=skill.levelDefinitions.find(l=>l.id===levelId)||currentLevel(skill,data()),endurance=level.requirements.find(r=>r.id==='endurance')||level.requirements[0];ctx.modal('Configure an untested trial',`<form class="fields"><label class="field">Requirement<select name="trial">${level.requirements.map(r=>`<option value="${r.id}" ${r.id===endurance.id?'selected':''}>${e(r.label)}</option>`).join('')}</select></label>${field('Qualifying practice days','sessions','number',level.sessions,'min="1" max="100" required')}${field('Sets','sets','number',endurance.sets,'min="1" max="20" required')}${field('Reps','reps','number',endurance.reps||0,'min="0" max="1000" required')}${field('Seconds','seconds','number',endurance.seconds||0,'min="0" max="3600" required')}${field('Meters','distance','number',endurance.distance||0,'min="0" max="100000" required')}${field('Resistance · lb','load','number',endurance.load||0,'min="0" max="2000" required')}${level.highVolumeEligible?'<label><input name="highvolume" type="checkbox" style="width:auto"> Use optional 4 × 100 endurance protocol</label><p class="legend">Only use this protocol if it suits this movement and your capacity. It never establishes maximum strength. It is not enabled for small-joint, heavy-compound, impact, or running paths.</p>':''}<p class="legend">Requirements with any proof history are protected.</p><button class="white">Save rule</button></form>`,async f=>{const old=level.requirements.find(r=>r.id===f.get('trial')),high=f.has('highvolume');if(high&&old.id!=='endurance')throw Error('4 × 100 applies only to the endurance trial.');const next={...old,sets:high?4:+f.get('sets')};for(const k of ['reps','seconds','distance','load']){const value=high&&k==='reps'?100:+f.get(k);if(value)next[k]=value;else delete next[k]}next.label=high?`4 × 100 at ${next.load||0} lb · controlled endurance`:`${next.sets} sets · ${next.reps||0} reps · ${next.seconds||0} s · ${next.distance||0} m · ${next.load||0} lb`;await actions.dispatch('saveDominanceRule',{skillId,levelId:level.id,requirement:next,sessions:+f.get('sessions'),protocol:high?'4x100':'standard'})})}
 function historyFilterDialog(){ctx.modal('Filter training history',`<form class="fields">${field('Date · optional','date','date',historyFilters.date||'')}<label class="field">Session type<select name="kind"><option value="">All</option>${['Main','Second','Extra','Sports','Custom'].map(k=>`<option ${k===historyFilters.kind?'selected':''}>${k}</option>`).join('')}</select></label><label class="field">Status<select name="status"><option value="">All</option>${['active','paused','completed','partial'].map(k=>`<option ${k===historyFilters.status?'selected':''}>${k}</option>`).join('')}</select></label>${field('Exercise name · optional','exercise','text',historyFilters.exercise||'')}${field('Muscle · optional','muscle','text',historyFilters.muscle||'')}<label class="field">Mode<select name="mode"><option value="">All</option>${modeOptions(historyFilters.mode)}</select></label><label class="field">Sport<select name="sport"><option value="">All</option><option ${historyFilters.sport==='Running'?'selected':''}>Running</option></select></label><label><input type="checkbox" name="dominance" style="width:auto" ${historyFilters.dominance?'checked':''}> Dominance proof sessions</label><label><input type="checkbox" name="pr" style="width:auto" ${historyFilters.pr?'checked':''}> Only sessions holding current PRs</label><button class="white">Apply filters</button></form>`,async f=>{historyFilters=Object.fromEntries(['date','kind','status','exercise','muscle','mode','sport'].map(k=>[k,f.get(k)]));historyFilters.pr=f.has('pr');historyFilters.dominance=f.has('dominance')})}
 async function handleAction(button){const a=button.dataset.action,id=button.dataset.id,skill=button.dataset.skill,level=button.dataset.level,index=+button.dataset.index;switch(a){case 'hungry':hungry();break;case 'extraArea':extraArea();break;case 'extraMuscle':extraMuscle(button.dataset.muscle);break;case 'freeExtra':{const x=exercise(button.dataset.exercise);await runSession('Extra',[plan(x)],x.name+' / extra',button.dataset.mode||'Normal',null,null,null,button.dataset.lowReadiness==='true'?{source:'still-hungry',lowReadiness:true}:null);break}case 'lightSecond':await runSession('Second',[plan(exercise('supported-hang'))],'Second / light skill','Light / Rebuild');break;case 'readiness':showReadiness(button.dataset.muscle);break;case 'soreness':soreness();break;case 'skillLevel':showLevel(skill,level);break;case 'proofStart':proofStart(skill,level,button.dataset.trial);break;case 'trial':logTrial(skill,level);break;case 'exerciseLibrary':library(button.dataset.exercise);break;case 'substitute':replaceMovement(id,index);break;case 'chooseReplacement':{const x=exercise(button.dataset.exercise);await actions.dispatch('replaceExercise',{sessionId:id,index,exercise:plan(x)});await ctx.refresh();ctx.showSession(id);break}case 'adaptive':adaptive(button.dataset.exercise);break;case 'keepLevel':document.querySelector('#modal').close();ctx.toast('Your level stays yours.');break;case 'personalCreate':personalCreate();break;case 'personalEdit':personalEdit(id);break;case 'planner':planner();break;case 'archiveRecurrence':await actions.dispatch('archivePersonalRecurrence',{recurrenceId:id});await ctx.refresh();planner();break;case 'equipment':equipment();break;case 'custom':openBuilder();break;case 'editTemplate':openBuilder(id);break;case 'builderAdd':readBuilder();builder.exercises.push(plan(exercise('curl')));renderBuilder();break;case 'builderRemove':readBuilder();builder.exercises.splice(index,1);renderBuilder();break;case 'builderUp':case 'builderDown':{readBuilder();const target=index+(a==='builderUp'?-1:1);[builder.exercises[index],builder.exercises[target]]=[builder.exercises[target],builder.exercises[index]];renderBuilder();break}case 'duplicateTemplate':await actions.dispatch('duplicateWorkoutTemplate',{templateId:id});await ctx.refresh();ctx.toast('Template duplicated.');break;case 'archiveTemplate':await actions.dispatch('archiveWorkoutTemplate',{templateId:id});await ctx.refresh();break;case 'usetemplate':{const t=data().templates.find(t=>t.id===id);await runSession('Custom',t.exercises,t.name,t.mode||'Normal',null,null,t.id);break}case 'carrySession':movementSession('Carry');break;case 'runSession':movementSession('Running');break;case 'ruleEditor':ruleEditor(skill,level);break;case 'historyFilters':historyFilterDialog();break;case 'sportsSettings':ctx.modal('Sports modules',`<form class="fields"><label><input type="checkbox" name="sports" style="width:auto" ${ctx.pref().sports?'checked':''}> Sports training enabled</label><label><input type="checkbox" name="Running" style="width:auto" ${ctx.pref().sportToggles?.Running!==false?'checked':''}> Running / walking module</label><p class="legend">Turning modules off removes their recommendations and preserves records, history, and mastery.</p><button class="white">Save</button></form>`,f=>actions.dispatch('saveRecord',{store:'preferences',record:{...ctx.pref(),sports:f.has('sports'),sportToggles:{...ctx.pref().sportToggles,Running:f.has('Running')}}}));break;default:return false}return true}
 function handleCommand(text){const t=text.toLowerCase().replaceAll('’',"'"),p=ctx.pref(),denied=category=>{ctx.modal('Caelum / memory controls',`<p>${category} access is off. Enable it in Settings to use these records.</p>`);return true};if(/dizz|chest pain|injur|severe pain/.test(t)){ctx.modal('Pause training', '<p>Stop the painful or alarming activity. Serious or persistent symptoms need appropriate medical help; do not push for a harder workout.</p>');return true}if(/move.*bae|bae.*tonight/.test(t)){if(!p.memory.schedule)return denied('Schedule');const block=data().events.filter(b=>b.category==='Personal Time'&&b.name.toLowerCase().includes('bae')&&!['COMPLETED','SKIPPED'].includes(b.status)&&b.date>=dayKey()).sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time))[0];if(block)personalEdit(block.id,true);else ctx.modal('Bae Time','<p>No upcoming Bae Time is scheduled yet.</p><button data-action="personalCreate">Protect Bae Time</button>');return true}if(/planner|personal time/.test(t)&&!/before/.test(t)){if(!p.memory.schedule)return denied('Schedule');planner();return true}if(/at home|at the gym|no equipment|travel/.test(t)){equipment();return true}if(/hungry|extra|energy|should i train|what.*train|give me arms|before bae/.test(t)){if(!p.memory.training)return denied('Training');const permitted={...data(),checkins:p.memory.metrics?data().checkins:[],soreness:p.memory.metrics?data().soreness:[],events:p.memory.schedule?data().events:[],goals:p.memory.goals?data().goals:[]};if(/arms/.test(t))extraMuscle('Biceps',permitted);else if(!p.memory.schedule){ctx.modal('Extra Training', '<p>Enable Schedule access if you want Caelum to account for protected commitments.</p><button data-action="extraArea">Choose training yourself</button>')}else hungry(permitted);return true}if(/readiness|sore/.test(t)){if(!p.memory.training||!p.memory.metrics)return denied('Training / health metrics');showReadiness();return true}if(/too easy|easy for|ready for more/.test(t)){if(!p.memory.training)return denied('Training');const latest=data().sessions.slice().sort((a,b)=>String(b.startedAt).localeCompare(String(a.startedAt)))[0];adaptive(latest?.exercises[0]?.exerciseId||'curl');return true}if(/can't do|cannot do/.test(t)){if(!p.memory.training)return denied('Training');const session=data().sessions.find(s=>['active','paused'].includes(s.status));if(session)replaceMovement(session.id,0);else library();return true}if(/what.*improv|new pr|my records/.test(t)){if(!p.memory.training)return denied('Training');const records=data().recordEvents.filter(r=>r.previous!==null).sort((a,b)=>b.at.localeCompare(a.at)).slice(0,8);ctx.modal('Caelum / improvements',`${records.map(r=>`<p><strong>${e(exercise(r.exerciseId)?.name||r.exerciseId)}</strong><br>${e(r.type)}: ${r.previous} → ${r.value} ${e(r.unit)} · ${e(r.date)}</p>`).join('')||'<p>No improved record is logged yet. Your first measurements establish a baseline.</p>'}<p>${data().masteryAwards.length} permanent mastery awards recorded. Open Profile for full records and history.</p>`);return true}if(/closest|pull.up progress|dominat/.test(t)){if(!p.memory.training||!p.memory.goals)return denied('Training / goals');const statuses=goalStatuses(data().goals,data().skillDefinitions,data().masteryAwards);ctx.modal('Caelum / capability map',`${data().skillDefinitions.map(s=>{const l=currentLevel(s,data()),v=evaluateLevel(s,l,data());return `<p><strong>${e(s.name)}</strong> · ${e(l.name)}<br>${v.trials.filter(t=>!t.complete).map(t=>e(t.pillar)).join(', ')||'Trials proved'} · ${v.days}/${l.sessions} qualifying days.</p>`}).join('')}<h3>First strict pull-up prerequisites</h3>${statuses.find(g=>g.id==='first-pullup')?.dependencies.map(g=>`<p>${g.proven?'✓':'○'} ${e(g.name)}</p>`).join('')||''}<p class="legend">Proof stays specific to each skill. I won't infer readiness or mastery from account XP.</p>`);return true}return false}
 function questsPage(){const goals=goalStatuses(data().goals,data().skillDefinitions,data().masteryAwards);return ctx.heading('Practice with a purpose.','Goal prerequisites reflect specific, repeatable proof.')+`<div class="grid">${goals.map(g=>`<article class="card"><span class="eyebrow">${g.id==='first-pullup'?'BOSS GOAL':'DEPENDENCY QUEST'}</span><h2 style="margin-top:16px">${e(g.name)}</h2><p>${g.proven?'Proved · capability recorded':g.ownProof?'Own proof recorded; dependencies remain':'Proof still ahead'}</p>${g.dependencies.map(d=>`<p class="legend">${d.proven?'✓':'○'} ${e(d.name)}</p>`).join('')}<button data-route="Dominance">Open skill paths ↗</button></article>`).join('')}<article class="card wide"><h2>Balance belongs here.</h2><p class="muted">Personal Time counts as a real commitment without turning a relationship into a quest grind.</p><button data-action="planner">Make room in your schedule</button></article></div>`}
 return {trainPage,dominancePage,questsPage,focusSection,todayExtras,personalBanner,profileExtras,historySection,handleAction,handleCommand,goalStatuses:()=>goalStatuses(data().goals,data().skillDefinitions,data().masteryAwards)};
}
